const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

const theme = {
  primary: "0F172A",    // Slate 900
  secondary: "334155",  // Slate 700
  accent: "2563EB",     // Blue 600
  light: "F1F5F9",      // Slate 100
  bg: "FFFFFF"          // White
};

function addBadge(slide, num) {
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText(String(num).padStart(2, '0'), {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });
}

// Slide 1: Cover
let slide1 = pres.addSlide();
slide1.background = { color: theme.bg };
slide1.addText("AI Model Landscape April 2026: Benchmarking Intelligence, Speed, and Cost Across 11 Frontier Models", {
  x: 1, y: 1.5, w: 8, h: 1.5,
  fontSize: 36, fontFace: "Arial", color: theme.primary, bold: true, align: "left"
});
slide1.addText("Equip decision-makers with a clear, data-driven comparison of top LLMs across intelligence, throughput, and cost so they can select the right model for their use case.", {
  x: 1, y: 3.5, w: 8, h: 1,
  fontSize: 18, fontFace: "Arial", color: theme.secondary, align: "left"
});

// Slide 2: Intelligence Index
let slide2 = pres.addSlide();
slide2.background = { color: theme.bg };
slide2.addText("Gemini 3.1 Pro Preview and GPT-5.4 Co-Lead the Intelligence Index at 57", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 22, fontFace: "Arial", color: theme.primary, bold: true
});

let data2 = [
  [{text: "Rank", options: {bold: true, color: "FFFFFF", fill: theme.primary}}, 
   {text: "Model", options: {bold: true, color: "FFFFFF", fill: theme.primary}}, 
   {text: "Provider", options: {bold: true, color: "FFFFFF", fill: theme.primary}}, 
   {text: "Intelligence Index", options: {bold: true, color: "FFFFFF", fill: theme.primary}}]
];
data2.push(["1", "Gemini 3.1 Pro Preview", "Google", "57"]);
data2.push(["2", "GPT-5.4 (xhigh)", "OpenAI", "57"]);
data2.push(["3", "Claude Opus 4.6 (max)", "Anthropic", "53"]);
data2.push(["4", "Muse Spark", "Meta", "52"]);
data2.push(["5", "Claude Sonnet 4.6 (max)", "Anthropic", "52"]);
data2.push(["6", "GLM-5.1", "Z AI", "51"]);
data2.push(["7", "Grok 4.20 0309 v2", "xAI", "49"]);
data2.push(["8", "Gemini 3 Flash", "Google", "46"]);
data2.push(["9", "DeepSeek V3.2", "DeepSeek", "42"]);
data2.push(["10", "NVIDIA Nemotron 3 Super", "NVIDIA", "36"]);
data2.push(["11", "gpt-oss-120B (high)", "OpenAI", "33"]);

slide2.addTable(data2, {
  x: 0.5, y: 1.2, w: 9, h: 4,
  fill: "FFFFFF", color: theme.secondary, fontSize: 12, border: {pt: 1, color: "E2E8F0"}, align: "left", valign: "middle"
});
addBadge(slide2, 2);

// Slide 3: Speed
let slide3 = pres.addSlide();
slide3.background = { color: theme.bg };
slide3.addText("gpt-oss-120B Tops Output Speed at 218 Tokens/s -- More Than 4x Faster Than Claude Opus 4.6", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 22, fontFace: "Arial", color: theme.primary, bold: true
});

let data3 = [
  {
    name: "Output Speed (Tokens/s)",
    labels: ["DeepSeek V3.2", "Claude Opus 4.6", "Claude Sonnet 4.6", "GLM-5.1", "GPT-5.4", "Gemini 3.1 Pro", "Gemini 3 Flash", "Nemotron 3", "Grok 4.20", "gpt-oss-120B"],
    values: [46, 49, 63, 64, 83, 118, 153, 172, 188, 218]
  }
];

slide3.addChart(pres.charts.BAR, data3, {
  x: 0.5, y: 1.2, w: 9, h: 3.8,
  barDir: "bar", chartColors: [theme.accent], showValue: true, showLegend: false,
  catAxisLabelColor: theme.secondary, valAxisLabelColor: theme.secondary, catAxisLabelFontSize: 11
});

addBadge(slide3, 3);

// Slide 4: Pricing
let slide4 = pres.addSlide();
slide4.background = { color: theme.bg };
slide4.addText("From $0.30 to $10 per Million Tokens: A 33x Pricing Gap Across Models", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 22, fontFace: "Arial", color: theme.primary, bold: true
});

let data4 = [
  {
    name: "Pricing ($/1M Tokens)",
    labels: ["gpt-oss", "DeepSeek", "Nemotron", "Gemini Flash", "GLM-5.1", "Grok 4.20", "Gemini Pro", "GPT-5.4", "Claude Sonnet", "Claude Opus"],
    values: [0.30, 0.30, 0.40, 1.10, 2.10, 3.00, 4.50, 5.60, 6.00, 10.00]
  }
];

slide4.addChart(pres.charts.BAR, data4, {
  x: 0.5, y: 1.2, w: 9, h: 3.8,
  barDir: "col", chartColors: [theme.secondary], showValue: true, showLegend: false,
  catAxisLabelColor: theme.secondary, valAxisLabelColor: theme.secondary
});

addBadge(slide4, 4);

// Slide 5: Tradeoffs
let slide5 = pres.addSlide();
slide5.background = { color: theme.bg };
slide5.addText("No Model Wins on All Three Axes: Navigating the Intelligence-Efficiency-Cost Frontier", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 20, fontFace: "Arial", color: theme.primary, bold: true
});

slide5.addImage({
  path: "/app/benchmark/assets/chart_intelligence_vs_output_tokens.jpg",
  x: 0.5, y: 1.2, w: 4.8, h: 3.6
});

let data5 = [
  [{text: "Metric", options: {bold: true, color: "FFFFFF", fill: theme.primary}}, 
   {text: "Proprietary Leader", options: {bold: true, color: "FFFFFF", fill: theme.primary}}, 
   {text: "Score", options: {bold: true, color: "FFFFFF", fill: theme.primary}}, 
   {text: "Open-Weight Leader", options: {bold: true, color: "FFFFFF", fill: theme.primary}}, 
   {text: "Score", options: {bold: true, color: "FFFFFF", fill: theme.primary}}]
];
data5.push(["Intelligence", "Gemini 3.1 Pro Preview", "57", "GLM-5.1", "51"]);
data5.push(["Speed (tokens/s)", "Gemini 3 Flash", "153", "gpt-oss-120B (high)", "218"]);
data5.push(["Price ($/1M tokens)", "Gemini 3 Flash", "$1.10", "gpt-oss-120B (high)", "$0.30"]);

slide5.addTable(data5, {
  x: 5.5, y: 1.5, w: 4.2, h: 1.5,
  fill: "FFFFFF", color: theme.secondary, fontSize: 10, border: {pt: 1, color: "E2E8F0"}, align: "left", valign: "middle"
});

addBadge(slide5, 5);

// Slide 6: Takeaways
let slide6 = pres.addSlide();
slide6.background = { color: theme.bg };
slide6.addText("Open Weights Close the Gap: GLM-5.1 Reaches 51 Intelligence at $2.10/M Tokens", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 20, fontFace: "Arial", color: theme.primary, bold: true
});

slide6.addText([
  { text: "Two-way tie at the top: ", options: { bold: true } },
  { text: "Gemini 3.1 Pro Preview and GPT-5.4 both score 57.\n" },
  { text: "Speed and intelligence are inversely correlated: ", options: { bold: true } },
  { text: "The fastest model scores only 33 on intelligence, while the smartest models operate at 49-118 tokens/s.\n" },
  { text: "Massive pricing spread: ", options: { bold: true } },
  { text: "A 33x cost gap separates the cheapest ($0.30/1M) from the most expensive ($10.00/1M).\n" },
  { text: "Open-weight models are closing the gap: ", options: { bold: true } },
  { text: "GLM-5.1 at 51 intelligence is within 10% of proprietary leaders, while being significantly cheaper.\n" },
  { text: "No single model wins on all three axes: ", options: { bold: true } },
  { text: "Choosing a model requires explicit trade-offs depending on the use case." }
], {
  x: 0.5, y: 1.2, w: 9, h: 3.8,
  fontSize: 18, fontFace: "Arial", color: theme.secondary, bullet: { type: "bullet" }, lineSpacing: 35
});

addBadge(slide6, 6);

// Save the PPTX
pres.writeFile({ fileName: '/app/output/final_deck.pptx' })
  .then(() => console.log('Final deck saved successfully!'))
  .catch(err => console.error(err));

